  const serviceInstances = services.filter((instance) => instance.name === serviceName);
  await registerService(serviceName, serviceInstances.map((instance) => instance.address));

  // Start heartbeat monitoring for each instance
  const heartbeatMonitor = async (instance: string) => {
    let lastHeartbeat = Date.now();
    while (true) {
      try {
        // Check if the instance is responding
