def find_path(graph, start, end, n):
    queue = [(start, [start])]
    visited = set()
    while queue:
        current, path = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)
        if current == end:
            if len(path) < n:
                continue
            return path[:n]
        for neighbor, edge in graph[current].items():
            if neighbor in visited:
