1. When the mouse is clicked (`mousedown` event), you can start drawing by setting the canvas context to drawing mode and saving the current mouse position.
2. When the mouse is released (`mouseup` event), you can stop drawing by setting the canvas context back to painting mode.
3. When the mouse is moved (`mousemove` event), you can update the drawing position by setting the canvas context to painting mode and drawing a line from the current position to the previous position.

Here's the full code example:
```javascript
var canvas = document.getElementById('drawingCanvas');
var ctx = canvas.getContext('2d');

// Set canvas to drawing mode
ctx.save();
ctx.setLineWidth(5);
ctx.beginPath();

// Save the current mouse position
var prevX = e.clientX - canvas.offsetLeft;
var prevY = e.clientY - canvas.offsetTop;

canvas.addEventListener('mousedown', function(e) {
  // Start drawing
  ctx.moveTo(e.clientX - canvas.offsetLeft, e.clientY - canvas.offsetTop);
});

canvas.addEventListener('mouseup', function(e) {
  // Stop drawing
  ctx.stroke();
  ctx.beginPath();
  ctx.setLineWidth(5);
  ctx.moveTo(prevX, prevY);
});

canvas.addEventListener('mousemove', function(e) {
  // Update drawing position
  ctx.lineTo(e.clientX - canvas.offsetLeft, e.clientY - canvas.offsetTop);
  ctx.stroke();
});
