```javascript
function addTimestampToImportUrl(css) {
  // Find the first @import line in the CSS code
  const importLineIndex = css.indexOf('@import');
  const importLine = css.substring(importLineIndex);

  // Get the current timestamp
  const timestamp = new Date().getTime();

  // Add the timestamp to the end of the @import URL
  const timestampedUrl = importLine.substring(importLineIndex) + `${timestamp}`;

  // Replace the original @import line with the timestamped version
  css = css.substring(0, importLineIndex) + timestampedUrl;

  return css;
}
```
