3. Create a function to generate a JWT:
```javascript
function generateToken(user) {
  return jwt.sign({ id: user.id }, secretKey, { expiresIn: '1h' });
}
```
This function takes in a user object and returns a JWT that contains the user's ID and expires after one hour.

4. Create a function to verify a JWT:
```javascript
function verifyToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ message: 'No token provided' });
  }

  jwt.verify(token, secretKey, (err, user) => {
    if (err) {
      return res.status(403).json({ message: 'Invalid token' });
    }

    req.user = user;
    next();
  });
}
```
This function extracts the token from the `Authorization` header of the request, verifies it using the secret key, and sets the `user` property of the request object. If the token is invalid, it returns a 403 status code with an error message.

