void multiply_fps(float32_t a, float32_t b, float32_t *result) {
    // Load floating point registers with input values
    VCVTS32.F16 = ((uint16_t)a << 16) | (uint16_t)b;
    VCVTS32.F32 = ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)b);

