pragma solidity ^0.8.0;

contract Asset {
    uint256 public totalSupply;
    uint256 public minted;
    uint256 public redeemed;
    uint256 public borrowed;
    uint256 public repaid;
    uint256 public liquidated;
    uint256 public interestRate;
    uint256 public reserveFactor;
    uint256 public closeFactor;

    constructor(uint256 _totalSupply = 1000000, uint256 _reserveFactor = 100, uint256 _closeFactor = 25) {
        totalSupply = _totalSupply;
        minted = 0;
        redeemed = 0;
        borrowed = 0;
        repaid = 0;
        liquidated = 0;
        interestRate = 0;
        reserveFactor = _reserveFactor;
        closeFactor = _closeFactor;
    }

    function mint(uint256 _amount) public {
        require(minted + _amount <= totalSupply, "Total supply exceeded");
        require(_amount > 0, "Amount must be greater than zero");

        minted += _amount;
        totalSupply += _amount;

        emit Transfer(msg.sender, _amount);
    }

    function redeem(uint256 _amount) public {
        require(borrowed + _amount <= totalSupply, "Total supply exceeded");
        require(_amount > 0, "Amount must be greater than zero");

        redeemed += _amount;
        borrowed -= _amount;

        emit Transfer(msg.sender, _amount);
    }

    function borrow(uint256 _amount) public {
        require(borrowed + _amount <= totalSupply, "Total supply exceeded");
        require(_amount > 0, "Amount must be greater than zero");

        borrowed += _amount;
        interestRate = calculateInterestRate();

        emit Transfer(msg.sender, _amount);
    }

    function repayBorrow(uint256 _amount) public {
        require(borrowed - _amount >= 0, "Insufficient borrowed balance");

        borrowed -= _amount;
        interestRate = calculateInterestRate();

        emit Transfer(msg.sender, _amount);
    }

    function liquidate(address _target, uint256 _amount) public {
        require(borrowed - _amount >= 0, "Insufficient borrowed balance");
        require(_amount > 0, "Amount must be greater than zero");

        liquidate(true);

        _target.transfer(borrowed);
        borrowed = 0;
        liquidate(false);
    }

