```solidity
pragma solidity ^0.8.0;

contract Compound {
    mapping(address => uint256) public balances;
    mapping(address => uint256) public borrows;
    mapping(address => uint256) public repays;
    mapping(address => uint256) public liquidations;
    mapping(address => uint256) public totalSupply;
    mapping(address => uint256) public minted;
    mapping(address => uint256) public redeemed;
    mapping(address => uint256) public borrowed;
    mapping(address => uint256) public reserves;
    mapping(address => uint256) public interestRate;
    mapping(address => uint256) public reserveFactor;
    mapping(address => uint256) public closeFactor;

