    uint256 public totalReserveBalance;
    uint256 public blockTime;
    uint256 public lastIndex;

    event Transfer(address from, uint256 value);

    constructor() {
        blockTime = block.timestamp;
        lastIndex = blockTime;
        totalBorrowBalance = 0;
        totalReserveBalance = 0;
        interestRate = 0;
        reserveFactor = 0.1;
        closeFactor = 0.2;
    }

    function mint(address _owner, uint256 _value) public {
        totalSupply[_owner] += _value;
        balances[_owner] += _value;
        emit Transfer(_owner, _value);
    }

    function redeem(address _owner, uint256 _value) public {
        require(balances[_owner] >= _value, "Insufficient balance");

        balances[_owner] -= _value;
        minted[_owner] += _value;
        emit Transfer(_owner, _value);
    }

    function borrow(address _owner, uint256 _value) public {
        require(balances[_owner] >= _value, "Insufficient balance");
        require(blockTime - lastIndex >= block.timestamp, "Interest rate not yet calculated");

        balances[_owner] -= _value;
        borrows[_owner] += _value;
        interestRate = calculateInterestRate();

        emit Transfer(_owner, _value);
    }

    function repayBorrow(address _owner, uint256 _value) public {
        require(borrows[_owner] >= _value, "Insufficient borrowed amount");
        require(blockTime - lastIndex >= block.timestamp, "Interest rate not yet calculated");

        borrows[_owner] -= _value;
        reserves[_owner] += _value;
        interestRate = calculateInterestRate();

        emit Transfer(_owner, _value);
    }

    function liquidate(address _target, uint256 _value) public {
        require(borrows[_target] >= _value, "Insufficient borrowed amount");
        require(blockTime - lastIndex >= block.timestamp, "Interest rate not yet calculated");

        liquidate(true);

        borrows[_target] -= _value;
        reserves[_target] += _value;
        liquidate(false);
    }

    function liquidate(bool _resolve) public {
        uint256 _borrowed = borrows[_target];
        uint256 _closeAmount = (closeFactor * _borrowed) / (1 - closeFactor);

        if (_resolve) {
            require(_borrowed >= _closeAmount, "Insufficient collateral");
            require(borrows[_target] - _closeAmount >= 0, "Insufficient borrowed amount");

            borrows.push(_borrowed);
            borrows.push(_closeAmount);

            emit Transfer(_target, _closeAmount);
            borrows[_target] -= _closeAmount;
        }
    }

    function calculateInterestRate() public view returns (uint256) {
        return (interestRate * utilization) + interestRate;
    }

    function updateInterestRate() public {
        interestRate = calculateInterestRate();
        lastIndex = blockTime;
        totalBorrowBalance = totalReserveBalance;
        totalReserveBalance = borrows.reduce((acc, cur) => acc + cur, 0);
    }

    function depositReserve(uint256 _value) public {
        require(reserves.length == 0, "Reserve already exists");

        reserves.push(_value);
        updateInterestRate();
    }

    function withdrawReserve() public {
        require(reserves.length > 0, "Reserve does not exist");
        require(borrows.length > 0, "Borrowed amount not yet calculated");

        uint256 _borrowed = borrows.pop();
        uint256 _reserved = reserves.pop();
        borrows.push(_borrowed + _reserved);
        reserves.push(_reserved);

        updateInterestRate();
    }
}
