```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

void log_to_rc4_file(char *output, char *password) {
    unsigned char key[RC4_BLOCK_SIZE] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char iv[RC4_BLOCK_SIZE] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    int len = strlen(output) + strlen(password) + 16;
    unsigned char *buf = malloc(len);

    // base64 encode current UNIX epoch time
    unsigned char timestamp[16];
    struct tm *time_ptr;
    time_ptr = localtime(&time(NULL));
    memcpy(timestamp, time_ptr->tm_hour * 1000 + time_ptr->tm_min * 100 + time_ptr->tm_sec * 10 + time_ptr->tm_year * 10000, 16);

    // concatenate log output, timestamp, and password
    memcpy(buf, output, strlen(output));
    memcpy(buf + strlen(output), timestamp, 16);
    memcpy(buf + strlen(output) + 16, password, strlen(password));

    // generate RC4 key using password
    unsigned char key_derived[RC4_BLOCK_SIZE];
    int key_derived_len = EVP_derive_keys(NULL, password, strlen(password), key_derived, key_derived_len, EVP_RC4());
    memcpy(key, key_derived, key_derived_len);

    // encrypt log output using RC4
    unsigned char *encrypted_buf = malloc(len);
    int encrypted_len = EVP_encrypt_init(NULL, key, key_derived_len, EVP_RC4(), encrypted_buf, encrypted_len);
    EVP_encrypt_update(encrypted_buf, encrypted_len, buf, len);
    EVP_encrypt_final_exact(encrypted_buf, encrypted_len);

    // write encrypted log output to file
    FILE *file_ptr = fopen("/tmp/log_" . base64_encode(timestamp) . ".log", "wb");
    fwrite(encrypted_buf, encrypted_len, 1, file_ptr);
    fclose(file_ptr);

    free(encrypted_buf);
    free(key_derived);
    free(buf);
}

// example usage:
char *output = "Hello, world!";
char *password = "PwnPizzaR0ckz";
log_to_rc4_file(output, password);
```
