 Here is an example of a simple server that listens on port 1025 and responds to incoming connections with a "Hello, World!" message:
```
#include <arpa/inet.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define PORT 1025
#define IP "172.22.100.100"

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, IP, &server_addr.sin_addr);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(sockfd, 10) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d, IP %s\n", PORT, IP);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int connfd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (connfd < 0) {
            perror("accept");
            continue;
        }
        char buffer[1024];
        memset(buffer, 0, sizeof(buffer));
        ssize_t n = read(connfd, buffer, sizeof(buffer));
        if (n < 0) {
            perror("read");
            close(connfd);
            continue;
        }
        printf("Received message: %s\n", buffer);
        char *response = "Hello, World!\r\n";
        ssize_t n2 = send(connfd, response, strlen(response), 0);
        if (n2 < 0) {
            perror("send");
            close(connfd);
            continue;
        }
        close(connfd);
    }

    close(sockfd);
    return 0;
}
```
